CREATE TABLE IF NOT EXISTS app_state (key TEXT PRIMARY KEY, json_data TEXT NOT NULL, version INTEGER NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS websites (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, url TEXT NOT NULL, imageUrl TEXT, driveFileId TEXT, "order" INTEGER NOT NULL DEFAULT 0, createdAt TEXT NOT NULL, updatedAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS announcements (id TEXT PRIMARY KEY, title TEXT NOT NULL, content TEXT NOT NULL, type TEXT NOT NULL DEFAULT 'general', category TEXT, date TEXT NOT NULL, dateStart TEXT, dateEnd TEXT, assignmentId TEXT, authorName TEXT NOT NULL DEFAULT 'ฝ่ายวิชาการ', isUrgent INTEGER NOT NULL DEFAULT 0, createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assignments (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT, department TEXT NOT NULL, dueDateEnd TEXT, points INTEGER DEFAULT 100, allowLateSubmission INTEGER DEFAULT 1, createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS submissions (id TEXT PRIMARY KEY, assignmentId TEXT NOT NULL, memberId TEXT NOT NULL, memberName TEXT NOT NULL, department TEXT, status TEXT NOT NULL DEFAULT 'submitted', submittedAt TEXT NOT NULL, note TEXT, filesJson TEXT);
CREATE TABLE IF NOT EXISTS documents (id TEXT PRIMARY KEY, title TEXT NOT NULL, category TEXT NOT NULL, description TEXT, docNumber TEXT, issueDate TEXT, uploaderId TEXT NOT NULL, uploaderName TEXT, fileJson TEXT, downloadCount INTEGER DEFAULT 0, createdAt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL, fullName TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'member', department TEXT, email TEXT, status TEXT NOT NULL DEFAULT 'approved', avatarUrl TEXT, createdAt TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_websites_order ON websites("order");
